return ['domain'=>'tranzly','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'ha','project-id-version'=>'tranzly','pot-creation-date'=>'2026-09-26T13:56:07+00:00','po-revision-date'=>'2026-09-26T13:56:07+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Tranzly'=>'Tranzly','https://zinndigital.com/wordpress-plugins/tranzly'=>'https://zinndigital.com/wordpress-plugins/tranzly','Multilingual WordPress, one post per language: linked translations of posts, pages, categories, media text, widgets and the site title, with your old Tranzly translations imported.'=>'WordPress mai harsuna da yawa, post ɗaya ga kowane harsha: fassarori masu alaƙa na posts, shafuka, rukuni, rubutun kafofin watsa labarai, widgets da taken shafin, tare da tsofaffin fassarorin ku na Tranzly da aka shigo da su.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'Masu samar da AI','The makers of ChatGPT. A good all-rounder.'=>'Masu ƙirƙirar ChatGPT. Mai amfani a kowane fanni mai kyau.','The makers of Claude. Strong at writing and careful reasoning.'=>'Masu samar da Claude. Suna da ƙarfi wajen rubuce-rubuce kuma suna da hankali wajen yin la\'akari.','Google\'s Gemini models. Fast and inexpensive.'=>'Samfuran Gemini na Google. Masu sauri da rahusa.','A European AI company with fast, inexpensive models.'=>'Kamfanin AI na Turai tare da sauri, samfura masu rahusa.','Low-cost models that are good at writing and code.'=>'Samfura masu rahusa wadanda ke da kyau wajen rubutu da shirya lamba.','One key for models from many different providers.'=>'Maɓalli guda ɗaya don samfuran daga masu samarwa daban-daban.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'Duk wani sabis da ke aiki kamar API na OpenAI, gami da samfurin da ke aiki akan kwamfutarka ko uwar garken ka.','General (used when nothing more specific is set)'=>'Gabaɗaya (ana amfani da shi lokacin da ba a saita wani abu na musamman ba)','Writing and rewriting'=>'Rubutawa da sake rubutawa','Translation'=>'Fassarar','Code and CSS'=>'Lamba da CSS','Sorry, you are not allowed to access this page.'=>'Yi hakuri, ba a ba ka izinin shiga wannan shafin ba.','These settings are shared by every plugin that uses them: %s.'=>'Ana raba waɗannan saitunan ta kowane plugin da ke amfani da su: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'An rufe makullan ku a cikin bayanan wannan rukunin yanar gizo kuma ana tura su ne kawai ga mai ba da sabis ɗin da kuka zaɓa - ba za a taɓa tura su zuwa gare mu ba.','Step 1 of 2: choose an AI provider'=>'Mataki na 1 na 2: zabi mai ba da sabis na AI','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'Kuna kawo naku madogara, don haka kuna biyan mai bayar da sabis ɗin kai tsaye don abin da kuka yi amfani da shi. Ba ku da tabbas? Kowane ɗayan waɗannan yana aiki sosai; za ku iya ƙara ƙarin daga baya.','Next'=>'Na gaba','Step 2 of 2: connect %s'=>'Mataki na 2 na 2: haɗa %s','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'Shigar da adireshin sabis ɗin da ke dace da OpenAI, wanda ya ƙare da /v1. Ana buƙatar maɓalli ne kawai idan sabis ɗin ya nemi ɗaya.','Open %s and sign in (or create a free account).'=>'Buɗe %s sannan ka shiga (ko ka ƙirƙiri sabon ajiya kyauta).','the %s API keys page'=>'shafin maɓallan API na %s','Create a new key and copy it.'=>'Ƙirƙiri sabon maɓalli sannan ka kofe shi.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'Saka shi a ƙasa sannan ka danna "Ajiye ka gwada". Muna tura ƙaramin buƙatu guda ɗaya don tabbatar yana aiki.','Most providers need a little credit on the account before a key works: %s.'=>'Yawancin masu ba da sabis na buƙatar ɗan kuɗi a cikin asusun kafin maɓalli ya yi aiki: %s.','add credit'=>'ƙara kuɗi','← Choose a different provider'=>'← Zabi wani mai ba da sabis daban','Address'=>'Adiireshi','Saved key ends in …%s — paste a new one to replace it'=>'Maɓallin da aka adana ya ƙare da …%s — liƙa sabo don maye gurbinsa','Key (optional)'=>'Maɓalli (zaɓaɓɓe)','API key'=>'Maɓullin API','Save and test'=>'Ajiye kuma a gwada','Providers'=>'Masu bada sabis','Provider'=>'Mai ba da sabis','Status'=>'Matsayi','Key'=>'Mabuɗi','Get a key'=>'Samu maɓalli','Test'=>'Gwaji','Remove'=>'Cire','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'An adana ta ta hanyar sabon sigar plugin: sabunta wannan plugin ɗin, ko kuma sake shigar da maɓallin.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'Ba za a iya buɗe maɓallin da aka ajiye ba kuma (an canza maɓallin tsaron shafin). Sake shigar da shi.','Not connected'=>'Ba a haɗa shi ba','Connected — last test passed %s'=>'An haɗa - gwajin ƙarshe ya yi nasara %s','Last test failed: %s'=>'Gwajin karshe ya gaza: %s','Connected — not tested yet'=>'An haɗa — ba a gwada ba tukuna','Which model to use'=>'Wane samfurin da za a yi amfani da shi','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ ta nuna shawararmu don wannan aikin. Jerin ya ƙunshi kowane samfurin da maɓallinku zai iya amfani da shi, wanda aka karanta kai tsaye daga mai bada sabis.','— Recommended for the provider —'=>'— An ba da shawarar ga mai bada sabis —','Save models'=>'Ajiye samfura','Refresh the model lists from the providers'=>'Sake sabunta jerin samfuran daga masu samarwa','best quality'=>'mafi kyau','lowest cost'=>'mafi ƙarancin farashi','fastest'=>'mafi sauri','Add a model yourself'=>'Kara abin koyi da kanka','A model came out today? Paste its exact name to use it straight away.'=>'An fitar da sabon samfuri a yau? A mannainiini sunansa daidai domin amfani da shi nan take.','Model name'=>'Sunan samfurin','Add model'=>'Ƙara samfurin','Recommended models list'=>'Jerin abubuwan da aka ba da shawarar','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'Ba a iya tabbatar da jerin samfuran da aka ba da shawarar ba, don haka ba a nuna shawarwari ba. Sake shigar da plugin ɗin, ko kuma kunna sabuntawa na yau da kullum a ƙasa.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'Jerin da ake amfani da shi an wallafa shi a ranar %s. Kowane sabuntawar fasalin ƙari yana kawo sabon abu.','Also check Zinn Digital® once a day for an updated list.'=>'Haka zalika, bincika Zinn Digital® sau ɗaya a rana don samun sabon jerin abubuwa.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Ana aika da sauƙaƙe buƙatar zazzagewa kawai: babu makulli, babu adireshin shafi, babu komai game da abun cikin ku. Jerin yana da sa hannu, kuma ana watsi da jerin da ya kasa gwajin sa hannu.','Last checked %1$s: %2$s.'=>'An duba ta ƙarshe %1$s: %2$s.','Save, and check now if turned on'=>'Ajiye, sannan a bincika yanzu idan an kunna','a newer list was installed'=>'an shigar da sabon jerin sunaye','already up to date'=>'an riga an sabunta','the download failed the signature check and was ignored'=>'an saukar da shi ya gaza binciken sa hannu kuma an yi watsi da shi','Zinn Digital® could not be reached; the current list stays in use'=>'Ba za a iya isa ga Zinn Digital® ba; jerin na yanzu zai ci gaba da amfani','turned off'=>'an kashe','Open'=>'Buɗe','Check their status page'=>'Bincika shafin yanayin su','Open your billing page'=>'Buɗe shafin ku na biyan kuɗi','Open your API keys page'=>'Buɗe shafin maɓallan API naka','Open the AI settings'=>'Buɗe saitunan AI','Sorry, you are not allowed to do that.'=>'Yi hakuri, ba a ba ka izinin yin hakan ba.','Unknown provider.'=>'Ba a san mai ba da sabis din ba.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Shigar da adireshin aikinku, alal misali http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'Wannan bai yi kama da maɓallin API ba. Sake kwafi shi, ba tare da guraben sarari ba.','Paste your API key first.'=>'Da farko a liƙa maɓallin API ɗinka.','Key removed.'=>'An cire maɓallin.','Models saved.'=>'An adana samfuran.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'Shigar dainiyan sunan samfurin, alal misali kamar yadda takardun bayanin mai ba da sabis suka rubuta shi.','Added %s. Choose it under "Which model to use".'=>'An kara %s. Zabi shi a karkashin "Wane samfurin za a yi amfani da shi".','Model removed.'=>'An cire samfurin.','Daily updates are off. The list that came with the plugin is used.'=>'An kashe sabuntawa kullum. Ana amfani da jerin da ya zo tare da plugin din.','Checked: %s.'=>'An bincika: %s.','Model lists refreshed.'=>'An sabunta jerin samfuran.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'Wani sabon sigar na ɗaya daga cikin plugins ɗinka ya adana maɓallin AI ɗinka. Sabunta wannan plugin ɗin, ko kuma ka sake shigar da maɓallin a cikin saitunan AI.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'Ba za a iya buɗe maɓallin AI da ka adana ba (an sauya maɓallin tsaro na shafin). Sake shigar da shi a cikin saitunan AI.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'Ba a saita AI ba tukuna. Ƙara maɓalli don mai ba da AI a cikin saitunan AI.','No model is chosen for this task. Pick one in the AI settings.'=>'Ba a zaɓi wani samfuri ba don wannan aikin. Zaɓi ɗaya a cikin saitunan AI.','That AI provider is not supported by this version of the plugin.'=>'Wannan mai ba da sabis na AI ba a goyi bayansa da wannan sigar ta plugin ba.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Wannan shafin bai iya isa ga sabis na AI naka ba. Tabbatar cewa yana aiki kuma ana iya isa ga adireshinsa daga sabar yanar gizonka (ba za a iya isa ga sabis da ke kan kwamfutarka ba daga wani shafin da aka karbi bakuncinsa).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Ba a iya samun %s a wannan shafin ba. Duba shafin su na halin yaki; idan yana aiki, mai masaukin bakin ka na iya toshe haɗin waje, ko kuma adreshin ba daidai ba ne.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s ya ce asusunka ba shi da kuɗi ko kuma adadin da ya rage. Ƙara kuɗi ko ɗaga iyakar a cikin asusunka tare da su, sannan a sake gwadawa.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s bai karɓi maɓallin ku ba. Yana iya zama an rubuta shi ba daidai ba, an soke shi, ko ya ƙare. Ƙirƙiri sabon maɓalli kuma liƙa shi a nan.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s ya ki amincewa da wannan roƙo na madannin ku. Madannin wataƙila ba shi da damar shiga wannan samfurin ko fasalin, ko kuma asusun ku na buƙatar tabbatarwa.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'Ba a samun samfurin "%1$s" daga %2$s don makullin ku. Zaɓi wani samfurin daban a cikin saitunan AI.','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'Tsarin ku na %2$s bai haɗa da samfurin "%1$s" ba. Zaɓi wani samfurin a cikin saitunan AI, ko haɓaka tsarin ku tare da su.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s na takaita saurin da maɓallin ku zai iya aika buƙatu. Jira minti guda sannan a ƙara gwadawa, ko kuma a ƙara iyakar ƙimar ku tare da su.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s yana fuskantar matsaloli a yanzu (akwai matsalar katsewar sabis ko cunkoso a ɓangarensu). Babu wata matsala game da saitunanka. Sake gwadawa nan ba da dadewa ba.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'Aikace-aikacen AI ya gaza saboda dalilin da ba za mu iya gane shi ba. Sake gwadawa; idan hakan ya ci gaba da faruwa, tuntuɓi sashen goyon baya tare da bayanan da ke ƙasa.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'Mai ba da sabis na AI ya ba da amsa a wata sifa da wannan plugin ɗin bai iya karantawa ba. Sake gwadawa; idan hakan ya ci gaba da faruwa, zaɓi wani samfurin ko tuntuɓi goyon baya.','Custom (OpenAI-compatible)'=>'Na Musamman (mai jituwa da OpenAI)','Save a key for this provider first.'=>'Ajiye maɓalli don wannan mai bada sabis ɗin da farko.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'Makullin ku yana aiki, amma mai ba da sabis ɗin bai lissafa wani samfurin rubutu ba a kansa. Ƙara samfurin da kanku a ƙasa.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'An haɗa. %1$s ya/ta amsa ta amfani da %2$s. Siffofin AI ɗinka suna shirye don amfani.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Ba a ba matsayin mai amfani da ku damar amfani da AI a wannan shafin ba. Tambayi mai gudanarwa.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Wannan shafin ya kai iyakar kasafin kuɗinsa na AI na wata-wata. Mai gudanarwa zai iya ƙara shi a cikin saitunan AI.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Wannan shafin ya kai iyakar buƙatunsa na AI na wata-wata. Mai gudanarwa zai iya ƙara ta a cikin saitunan AI.','Usage and cost'=>'Amfani da tsada','The log, limits and role permissions apply to AI used through: %s.'=>'Littafin shiga, iyakoki da izinin matsayi suna aiki ga AI da ake amfani da ita ta hanyar: %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'Kudin suna da kusan zatowa, an lissafa su daga farashin da aka buga; samfurin da babu wani sanannen farashin shi yana ƙidaya azaman sifili.','This month: %1$s requests, about %2$s.'=>'Wannan watan: buƙatun %1$s, kusan %2$s.','When'=>'Lokaci','Who'=>'Wane','Used for'=>'Yi amfani da shi don','Model'=>'Samfurin','Tokens in / out'=>'Wajen Tokens / Waje','About'=>'Game da','Result'=>'Sakamako','No AI requests have been made yet.'=>'Ba a yi buƙatun AI ba tukuna.','Done'=>'An gama','Limits and permissions'=>'Iyaka da izini','Monthly spending limit (US dollars)'=>'Iyakar kashe kuɗi ta kowane wata (dalar US)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'Bar shi ba komai don babu iyaka. AI zai tsaya na sauran watan da zarar kusan farashin ya kai hakan.','Monthly request limit'=>'Iyakokin buƙatu na kowane wata','Leave empty for no limit.'=>'Bar shi da babu komai don babu iyaka.','Who may use AI'=>'Wane ne zai iya amfani da AI','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'Cire daukacin zabubbuka domin ba wa kowa damar amfani da AI wanda zai iya amfani da sassan plugin din. Masu gudanarwa za su iya amfani da shi kowane lokaci.','Save limits and permissions'=>'Ajiye iyakoki da izini','Limits and permissions saved.'=>'An adoke da izini an adana.','That language is not one of this site\'s languages.'=>'Wannan harshe ba ya cikin harsunan da wannan shafin ke amfani da su.','A translation must be the same kind of content as the original.'=>'Dole fassarar ta zama iri ɗaya da ta asali.','Choose one of the site\'s other languages.'=>'Zaɓi wani daga cikin sauran harsunan shafin yanar gizon.','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'Rubutun allo na admin ba ya nan a cikin wannan kwafin na plugin ɗin. Sake shigar da shi daga fakitin da aka fitar.','This screen needs JavaScript.'=>'Wannan allon yana buƙatar JavaScript.','Choose a language'=>'Zaɓi harshe','Upgrade'=>'Haɓaka','Pricing'=>'Farashin kaya','Start Trial'=>'Fara Gwaji','Account'=>'Asusun ajiyar','Contact Us'=>'Tuntube Mu','Affiliation'=>'Alaka','the kind of softwarePlugin'=>'Fifikal','greetingHey %s,'=>'Sannu %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'Yi rijista domin karɓar sanarwar imel don sabunta tsaro da fasali, abubuwan ilimi, da lokaci-lokaci, da kuma raba wasu basic WordPress yanayin muhalli. Wannan zai taimake mu mu sanya %s ya fi dacewa da shafin ku kuma mafi kyau wajen yin abin da kuke buƙatar ya yi.','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'Yi rajista don samun sanarwar imel don sabunta tsaro & siffofi, abubuwan ilimi, da lokaci-lokaci na musamman, da kuma raba wasu mahimman bayanan muhalli na WordPress.','If you skip this, that\'s okay! %1$s will still work just fine.'=>'Idan ka tsallake wannan, ba komai! %1$s zai ci gaba da aiki da kyau sosai.','Allow & Continue'=>'Ba da izini & Ci gaba','verbSkip'=>'Tsallake','Skipping, please wait'=>'Ana tsallakewa, don Allah a jira','Continue'=>'Ci gaba','Please wait'=>'Da fatan za a jira','as activating pluginActivating'=>'Ana kunnawa','This will allow %s to'=>'Wannan zai ba da damar %s su','Privacy Policy'=>'Manufar Sirri','Terms of Service'=>'Sharuddan Sabis','License Agreement'=>'Yarda da Lasisi','Have a license key?'=>'Kuna da madannin lasisi?','Activate License'=>'Kunna Lasisi','View Basic Profile Info'=>'Duba Cikakken Bayanin Asali','Your WordPress user\'s: first & last name, and email address'=>'Sunan mai amfani na WordPress: sunan farko & na ƙarshe, da adireshin imel','View Basic Website Info'=>'Dubi Cikakkun Bayanan Yanar Gizo na Asali','Homepage URL & title, WP & PHP versions, and site language'=>'URL da taken shafin gida, nau\'ikan WP da PHP, da harshen shafin','View Basic %s Info'=>'Duba Babban Bayanin %s','Current %s & SDK versions, and if active or uninstalled'=>'Na yanzu %s & nau\'ikan SDK, kuma idan suna aiki ko ba a shigar da su ba','Newsletter'=>'Wasiƙar labarai','Updates, announcements, marketing, no spam'=>'Sabuntawa, sanarwa, tallace-tallace, babu spam','View Diagnostic Info'=>'Duba Bayanin Matsala','WordPress & PHP versions, site language & title'=>'Sigogin WordPress da PHP, yaren shafin yanar gizo da taken shafi','View Plugins & Themes List'=>'Duba Lissafin Fਲugins & Jigo-jigo','Names, slugs, versions, and if active or not'=>'Sunaye, alamomi, juzu\'i, da ko a kunne suke ko a\'a','optional'=>'na zaɓi ba','Never miss an important update'=>'Karɓe kowane sabuntawa mai mahimmanci','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'Mun gabatar da wannan zaɓi don kar ku taɓa rasa muhimmin sabuntawa kuma ku taimaka mana mu sa %s ya fi dacewa da shafin ku kuma ya fi kyau wajen yin abin da kuke buƙata ya yi.','Thank you for updating to %1$s v%2$s!'=>'Na gode da sabuntawa zuwa %1$s v%2$s!','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'Dole ne prefix ya zama haruffa kanana 1 zuwa 8 ko lambobi, ya fara da harafi, kuma kada ya sanya wa plugin ɗin suna.','"%s" is not a language code. Use a WordPress locale such as fr_FR or de_DE.'=>'"%s" ba lambar yare ba ne. Yi amfani da wani locale na WordPress kamar fr_FR ko de_DE.','List at least one language.'=>'Lisƙa aƙalla harshe ɗaya.','You are not allowed to translate this item.'=>'Ba a baka izinin fassara wannan abu ba.','This item already has a version in that language.'=>'Wannan abu yana da fasali a cikin wannan harshe tuni.','The value for %s is not one of the allowed choices.'=>'Darajar %s ba ta cikin abubuwan da aka yarda da su ba.','This item\'s group already has a %1$s version (#%2$d).'=>'Rungiyar wannan abu tana da nau\'in %1$s riga (#%2$d).','An item cannot be its own translation.'=>'Ba zai yiwu abu ya zama fassarar kansa ba.','That item is already a translation of something else. Unlink it first.'=>'Wannan abu fassara ce ta wani abu daban. A cire haɗin farko.','The translation link could not be saved.'=>'Ba a iya adana hanyar fassara ba.','That text cannot be translated here.'=>'Ba za a iya fassara wannan rubutu a nan ba.','That media text cannot be translated here.'=>'Ba za a iya fassara rubutun kafofin watsa labarai a nan ba.','A translation can be published or kept as a draft.'=>'Ana iya buga fassarar ko a adana ta a matsayin daftari.','You are not allowed to publish this kind of content.'=>'Ba a ba ka izinin buga irin wannan abun ciki ba.','This item is already written in that language.'=>'Wannan abu an riga an rubuta shi a wannan harshen.','You are not allowed to change that translation.'=>'Ba a ba ku izinin canza wannan fassarar ba.','This translation was edited by a person (or imported), so it is protected. Unlock it to translate it again.'=>'Wannan fassarar mutum ne ya gyara ta (ko kuma aka shigo da ita), don haka tana da kariya. Buɗe ta don sake fassara ta.','No translation engine is set up yet. Add a key for one in Tranzly → Engines.'=>'Ba a saita injin fassara ba tukuna. Ƙara maɓalli don ɗaya a cikin Tranzly → Engines.','That translation engine is not available on this site.'=>'Ba a samun wannan injin fassara a wannan shafin ba.','That translation engine is not set up yet: add its key first.'=>'Ba a saita injin fassarar nan ba tukuna: da farko a ƙara maɓallinsa.','%s did not return a translation for every part of this item. Nothing was changed.'=>'%s bai dawo da fassarar kowane bangare na wannan abu ba. Ba a canza komai ba.','An engine id must be lowercase letters, digits and hyphens.'=>'Dole idin injini ya zama ƙananan baƙaƙe, lamba, da kuma alamar raba kalma (hyphens).','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'Neil Lock, Shugaban Zinn Digital® Ltd ne ya gina shi','Version %s'=>'Mawadata %s','Tranzly website'=>'Shafin yanar gizo na Tranzly','Zinn Digital® website'=>'Shafin yanar gizo na Zinn Digital®','Settings saved.'=>'An adana saitunan.','See the Pro plans and pricing'=>'Duba tsare-tsaren Pro da farashinsu','Languages'=>'Harsuna','The first language is the one your content is written in. Visitors switch with the language switcher block.'=>'Harshe na farko shine wanda aka rubuta abubuwan da ke cikin ku. Baƙi suna canzawa tare da tubalin sauya harshe.','(default)'=>'(tsohuwa)','Locale code'=>'Lambar yanki','For example fr_FR'=>'Misali fr_FR','Name (optional)'=>'Sunane (ba tilas ba ne)','For example Français'=>'Misali Français','Add language'=>'Ƙara harshe','Front-end output'=>'Abubuwan da ke fita a ɓangaren masu amfani','Class name prefix'=>'Gabatarwar sunan ajin','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'Kowane suna na ajin da fasahar ta buga a shafukanku yana farawa da wannan maƙunsar, ta yadda shafukan ba za su bayyana wace fasaha ce ta gina su ba. Haruffa ƙanana 1 zuwa 8 ko lambobi, suna farawa da harafi.','Beta updates'=>'Sabuntawar Beta','This site receives beta versions as updates.'=>'Wannan shafin yana karɓar nau\'ikan beta a matsayin sabuntawa.','This site receives stable versions only.'=>'Wannan shafin yana karɓar ingantattun sassa kawai.','Change this on the Account page'=>'Canza wannan a shafin Asusu','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'Ana ba da sigogin Beta ga shigarwar Pro masu lasisi waɗannan da ke haɗa da asusunsu. Da zarar an haɗa, zaku iya shiga daga shafin Asusun.','Save settings'=>'Ajiye saituna','Add a second language under Tranzly in the admin menu, and the switcher appears here.'=>'Ƙara harshe na biyu a ƙarƙashin Tranzly a cikin menu na gudanarwa, kuma maballin canzawa zai bayyana a nan.','Switcher'=>'Mai sauyawa','Accessible label'=>'Alamar da za a iya karantawa','block titleLanguage switcher'=>'Canjin harshe','block descriptionLinks to this page in each of the site\'s languages. It renders nothing until two or more languages are listed.'=>'Hadin gwiwa zuwa wannan shafin a kowane harshe na shafin. Yana nuna komai ba sai an lissafa harsuna biyu ko fiye ba.','block keywordlanguage'=>'Harshe','block keywordswitcher'=>'mai sauyawa','block keywordtranslation'=>'fassara']];